// Parse and validate incoming message
const message = $input.first().json;

// Required fields validation
if (!message.from_agent || !message.content) {
  return [{
    json: {
      error: 'Missing required fields: from_agent, content',
      status: 'invalid'
    }
  }];
}

// Determine message type and routing
const messageType = message.type || 'direct';
const priority = message.priority || 'normal';
const timestamp = new Date().toISOString();

// Create enhanced message object
const enhancedMessage = {
  ...message,
  id: `msg_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
  timestamp,
  messageType,
  priority,
  status: 'pending_routing'
};

return [{
  json: enhancedMessage
}];

// Broadcast to all agents in party
const message = $input.first().json;
const partyId = message.party_id || 'default_party';

// Get all agents in the party (mock data for now)
const allAgents = [
  'agent_dungeon_master',
  'agent_narrator', 
  'agent_combat_manager',
  'agent_scene_coordinator',
  'agent_character_ai'
];

// Filter out sender
const recipients = allAgents.filter(agent => agent !== message.from_agent);

// Create individual messages for each recipient
const broadcastMessages = recipients.map(recipient => ({
  ...message,
  to_agent: recipient,
  routing_type: 'broadcast',
  broadcast_to: recipients,
  processed_at: new Date().toISOString()
}));

return broadcastMessages.map(msg => ({
  json: msg
}));

// Direct message to specific agent
const message = $input.first().json;

if (!message.to_agent) {
  return [{
    json: {
      error: 'Direct messages require to_agent field',
      status: 'routing_failed'
    }
  }];
}

return [{
  json: {
    ...message,
    routing_type: 'direct',
    processed_at: new Date().toISOString()
  }
}];

// Priority message handling
const message = $input.first().json;

// Check for urgent messages
if (message.priority === 'urgent' || message.priority === 'critical') {
  // Add priority handling
  return [{
    json: {
      ...message,
      priority_flag: true,
      escalation_level: message.priority === 'critical' ? 'high' : 'medium',
      requires_immediate_attention: true
    }
  }];
}

return [{
  json: message
}];

// Log message delivery and update status
const deliveryResult = $input.first().json;
const originalMessage = $('Parse Message').first().json;

const deliveryLog = {
  message_id: originalMessage.id,
  from_agent: originalMessage.from_agent,
  to_agent: originalMessage.to_agent,
  message_type: originalMessage.messageType,
  priority: originalMessage.priority,
  delivery_status: deliveryResult.success ? 'delivered' : 'failed',
  delivered_at: new Date().toISOString(),
  delivery_response: deliveryResult
};

return [{
  json: {
    ...deliveryLog,
    status: 'completed',
    response: {
      message_id: originalMessage.id,
      status: deliveryResult.success ? 'delivered' : 'failed',
      timestamp: deliveryLog.delivered_at
    }
  }
}];
